        /// <summary>
        /// Adds the client detail fields (phone, email, employment type, entry date, photo,
        /// contracts/groups/qualifications/notes summaries) to the seeded Address Detail template.
        /// Only touches rows still equal to the original seeded content, so an administrator who
        /// already customised the template in the Report Designer keeps their own version.
        /// </summary>
        public static void ExtendAddressDetailWithClientDetails(MigrationBuilder migrationBuilder)
        {
            migrationBuilder.Sql(
                $@"UPDATE public.report_templates
                  SET sections = '{AddressDetailSectionsV2}',
                      update_time = '{SeedTimestamp}',
                      current_user_updated = '{SeedUser}'
                  WHERE id = '{AddressDetailTemplateId}'
                    AND sections::jsonb = '{AddressDetailSectionsV1}'::jsonb;");
        }

